outcome.text:
以下を `index.html` として保存し、ブラウザーで開くと使えます。標準税率10%と軽減税率8%を切り替えて、税込価格を計算します。

```html
<!doctype html>
<html lang="ja">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>税込価格計算ツール</title>
  <style>
    body { font-family: sans-serif; max-width: 420px; margin: 40px auto; padding: 0 16px; }
    label { display: block; margin: 16px 0 6px; }
    input, select, button { box-sizing: border-box; width: 100%; padding: 10px; font-size: 16px; }
    #result { margin-top: 20px; font-size: 1.2rem; font-weight: bold; }
  </style>
</head>
<body>
  <h1>税込価格計算ツール</h1>

  <label for="price">税抜価格（円）</label>
  <input id="price" type="number" min="0" step="1" placeholder="例：1000">

  <label for="rate">税率</label>
  <select id="rate">
    <option value="0.10">標準税率（10%）</option>
    <option value="0.08">軽減税率（8%）</option>
  </select>

  <button id="calculate" type="button">計算する</button>
  <p id="result" aria-live="polite"></p>

  <script>
    const priceInput = document.getElementById("price");
    const rateSelect = document.getElementById("rate");
    const result = document.getElementById("result");

    document.getElementById("calculate").addEventListener("click", () => {
      const price = Number(priceInput.value);

      if (priceInput.value === "" || !Number.isFinite(price) || price < 0) {
        result.textContent = "0以上の税抜価格を入力してください。";
        return;
      }

      const total = price * (1 + Number(rateSelect.value));
      result.textContent = `税込価格：${total.toLocaleString("ja-JP")}円`;
    });
  </script>
</body>
</html>
```

以下を `.html` ファイルとして保存して開くと、借入額・年利・返済期間を変更できる計算機として使えます。返済額は元利均等返済で計算します。

```html
<!doctype html>
<html lang="ja">
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>住宅ローン返済額計算機</title>

<h1>住宅ローン返済額計算機</h1>

<label>借入額（円）
  <input id="amount" type="number" value="30000000" min="0" step="10000">
</label>
<br>
<label>年利（%）
  <input id="rate" type="number" value="1.5" min="0" step="0.01">
</label>
<br>
<label>返済期間（年）
  <input id="years" type="number" value="35" min="1" step="1">
</label>

<p>毎月の返済額：<strong id="result"></strong></p>

<script>
  const inputs = ["amount", "rate", "years"];
  inputs.forEach(id => document.getElementById(id).addEventListener("input", calculate));

  function calculate() {
    const amount = Number(document.getElementById("amount").value);
    const annualRate = Number(document.getElementById("rate").value);
    const years = Number(document.getElementById("years").value);
    const result = document.getElementById("result");

    if (amount <= 0 || annualRate < 0 || years <= 0) {
      result.textContent = "有効な値を入力してください";
      return;
    }

    const monthlyRate = annualRate / 100 / 12;
    const payments = years * 12;
    const monthlyPayment = monthlyRate === 0
      ? amount / payments
      : amount * monthlyRate / (1 - Math.pow(1 + monthlyRate, -payments));

    result.textContent = Math.round(monthlyPayment).toLocaleString("ja-JP") + "円";
  }

  calculate();
</script>
</html>
```

この計算は、金利が返済期間中一定で、毎月返済する前提です。

以下を `損益分岐点シミュレーター.html` として保存し、ブラウザーで開くと使えます。価格や費用を変更して「計算」を押してください。

```html
<!doctype html>
<html lang="ja">
<meta charset="utf-8">
<title>損益分岐点シミュレーター</title>

<h1>損益分岐点シミュレーター</h1>

<label>月間固定費（円）
  <input id="fixed" type="number" value="3000000" min="0">
</label><br>

<label>販売価格（円／個）
  <input id="price" type="number" value="5000" min="0">
</label><br>

<label>変動費（円／個）
  <input id="variable" type="number" value="2000" min="0">
</label><br><br>

<button onclick="calculate()">計算</button>
<p id="result" aria-live="polite"></p>

<script>
function calculate() {
  const fixed = Number(document.getElementById("fixed").value);
  const price = Number(document.getElementById("price").value);
  const variable = Number(document.getElementById("variable").value);
  const result = document.getElementById("result");

  if (fixed < 0 || price < 0 || variable < 0) {
    result.textContent = "金額は0以上で入力してください。";
  } else if (price <= variable) {
    result.textContent = "販売価格が変動費以下のため、損益分岐点を計算できません。";
  } else {
    const units = Math.ceil(fixed / (price - variable));
    result.textContent =
      `損益分岐点の販売数：${units.toLocaleString()}個` +
      `（計算値：${(fixed / (price - variable)).toLocaleString()}個）`;
  }
}
calculate();
</script>
</html>
```

初期値では、損益分岐点は **1,000個** です。端数が出る場合、販売数は切り上げて表示します。

以下を `tsumitate.html` として保存し、ブラウザーで開くと使えます。参考資料の複利・月次の式で計算します。

```html
<!doctype html>
<html lang="ja">
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>積立投資の試算</title>

<h1>積立投資の試算</h1>

<label>毎月の積立額（円）
  <input id="monthly" type="number" value="30000" min="0">
</label><br>

<label>年利回り（%）
  <input id="annualRate" type="number" value="3" step="0.1">
</label><br>

<label>積立期間（年）
  <input id="years" type="number" value="20" min="0">
</label><br>

<button id="calculate">試算する</button>

<h2>試算結果</h2>
<p>将来の金額：<strong id="futureValue">—</strong></p>
<p>積立元本：<span id="principal">—</span></p>

<script>
  const yen = value =>
    Math.round(value).toLocaleString("ja-JP") + "円";

  function calculate() {
    const monthly = Number(document.getElementById("monthly").value);
    const annualRate = Number(document.getElementById("annualRate").value);
    const years = Number(document.getElementById("years").value);

    if (monthly < 0 || years < 0 || !Number.isFinite(annualRate)) {
      document.getElementById("futureValue").textContent = "入力値を確認してください";
      document.getElementById("principal").textContent = "—";
      return;
    }

    const months = years * 12;
    const monthlyRate = annualRate / 100 / 12;

    // 月利が0の場合は、積立元本をそのまま将来の金額とする
    const futureValue = monthlyRate === 0
      ? monthly * months
      : monthly * ((Math.pow(1 + monthlyRate, months) - 1) / monthlyRate);

    document.getElementById("futureValue").textContent = yen(futureValue);
    document.getElementById("principal").textContent = yen(monthly * months);
  }

  document.getElementById("calculate").addEventListener("click", calculate);
  calculate();
</script>
</html>
```

初期設定（毎月3万円・年利回り3%・20年）で試算します。税金や手数料は、この計算式には含まれていません。

以下を `index.html` として保存すると、ブラウザーで使えます。税率を切り替えると税込価格を自動で計算します。

```html
<!DOCTYPE html>
<html lang="ja">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>税込価格計算ツール</title>
  <style>
    body {
      max-width: 480px;
      margin: 40px auto;
      padding: 0 16px;
      font-family: sans-serif;
      color: #222;
    }
    label, select, input {
      display: block;
      width: 100%;
      margin-top: 8px;
    }
    input, select {
      box-sizing: border-box;
      padding: 10px;
      font-size: 1rem;
    }
    .field { margin-bottom: 20px; }
    #result { font-size: 1.4rem; font-weight: bold; }
  </style>
</head>
<body>
  <h1>税込価格計算ツール</h1>

  <div class="field">
    <label for="price">税抜価格（円）</label>
    <input id="price" type="number" min="0" step="1" placeholder="例：1000">
  </div>

  <div class="field">
    <label for="taxRate">税率</label>
    <select id="taxRate">
      <option value="0.10">標準税率（10%）</option>
      <option value="0.08">軽減税率（8%）</option>
    </select>
  </div>

  <p>税込価格</p>
  <p id="result" aria-live="polite">—</p>

  <script>
    const priceInput = document.getElementById("price");
    const taxRateSelect = document.getElementById("taxRate");
    const result = document.getElementById("result");

    function calculate() {
      const price = Number(priceInput.value);
      if (priceInput.value === "" || !Number.isFinite(price) || price < 0) {
        result.textContent = "—";
        return;
      }

      const inclusivePrice = price * (1 + Number(taxRateSelect.value));
      result.textContent = `${inclusivePrice.toLocaleString("ja-JP")} 円`;
    }

    priceInput.addEventListener("input", calculate);
    taxRateSelect.addEventListener("change", calculate);
  </script>
</body>
</html>
```

計算式は「税抜価格 ×（1 ＋ 税率）」です。

以下の計算機で試算できます。毎月の積立額・年利回り・積立期間を入力してください。

```html
<label>毎月の積立額（円）<input id="monthly" type="number" value="30000" min="0"></label><br>
<label>年利回り（%）<input id="rate" type="number" value="3" step="0.1"></label><br>
<label>積立期間（年）<input id="years" type="number" value="20" min="1"></label><br>
<button onclick="calculate()">試算する</button>
<p id="result">将来の金額：約9,845,000円</p>

<script>
function calculate() {
  const monthly = Number(document.getElementById("monthly").value);
  const annualRate = Number(document.getElementById("rate").value) / 100;
  const years = Number(document.getElementById("years").value);
  const months = years * 12;
  const monthlyRate = annualRate / 12;

  const amount = monthlyRate === 0
    ? monthly * months
    : monthly * ((1 + monthlyRate) ** months - 1) / monthlyRate;

  document.getElementById("result").textContent =
    `将来の金額：約${Math.round(amount).toLocaleString()}円`;
}
</script>
```

初期値（毎月3万円・年利回り3%・20年）の試算は約984万5,000円です。実際の運用成果や手数料・税金は考慮していません。

以下を `simulator.html` として保存し、ブラウザーで開くと使えます。固定費・販売価格・変動費を変更すると、損益分岐点の販売数を計算します。

```html
<!doctype html>
<html lang="ja">
<meta charset="utf-8">
<title>損益分岐点シミュレーター</title>

<h1>損益分岐点シミュレーター</h1>

<label>固定費（月額・円）
  <input id="fixed" type="number" value="3000000" min="0">
</label><br>

<label>販売価格（円／個）
  <input id="price" type="number" value="5000" min="0">
</label><br>

<label>変動費（円／個）
  <input id="variable" type="number" value="2000" min="0">
</label><br><br>

<button onclick="calculate()">計算</button>
<p id="result">損益分岐点の販売数：1,000個</p>

<script>
  function calculate() {
    const fixed = Number(document.getElementById("fixed").value);
    const price = Number(document.getElementById("price").value);
    const variable = Number(document.getElementById("variable").value);
    const result = document.getElementById("result");

    if (price <= variable) {
      result.textContent = "販売価格は変動費を上回る必要があります。";
      return;
    }

    const units = Math.ceil(fixed / (price - variable));
    result.textContent = `損益分岐点の販売数：${units.toLocaleString()}個`;
  }
</script>
</html>
```

参考資料の初期値では、損益分岐点は **1,000個** です。

以下を `loan-calculator.html` として保存し、ブラウザーで開くと使えます。借入額・年利・返済期間を動かすと、毎月の返済額が更新されます。

```html
<!DOCTYPE html>
<html lang="ja">
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>住宅ローン返済額計算機</title>

<div class="calculator">
  <h1>住宅ローン返済額計算機</h1>

  <label>
    借入額
    <input id="loan" type="range" min="0" max="100000000" step="100000" value="30000000">
    <output id="loanValue"></output>
  </label>

  <label>
    年利
    <input id="rate" type="range" min="0" max="10" step="0.01" value="1.5">
    <output id="rateValue"></output>
  </label>

  <label>
    返済期間
    <input id="years" type="range" min="1" max="50" step="1" value="35">
    <output id="yearsValue"></output>
  </label>

  <p>毎月の返済額</p>
  <strong id="payment"></strong>
</div>

<style>
  body { font-family: sans-serif; margin: 2rem; }
  .calculator { max-width: 520px; }
  label { display: block; margin: 1.5rem 0; }
  input[type="range"] { display: block; width: 100%; margin-top: .5rem; }
  output { display: block; margin-top: .3rem; }
  strong { font-size: 1.8rem; }
</style>

<script>
  const loan = document.getElementById("loan");
  const rate = document.getElementById("rate");
  const years = document.getElementById("years");

  const yen = value => Math.round(value).toLocaleString("ja-JP") + "円";

  function update() {
    const principal = Number(loan.value);
    const annualRate = Number(rate.value);
    const months = Number(years.value) * 12;
    const monthlyRate = annualRate / 100 / 12;

    const payment = monthlyRate === 0
      ? principal / months
      : principal * monthlyRate /
        (1 - Math.pow(1 + monthlyRate, -months));

    document.getElementById("loanValue").textContent = yen(principal);
    document.getElementById("rateValue").textContent = annualRate.toFixed(2) + "%";
    document.getElementById("yearsValue").textContent = years.value + "年";
    document.getElementById("payment").textContent = yen(payment);
  }

  [loan, rate, years].forEach(input => input.addEventListener("input", update));
  update();
</script>
</html>
```

元利均等返済の式で計算し、年利0%の場合は借入額を返済回数で割って表示します。スライダーの範囲は、借入額0〜1億円・年利0〜10%・返済期間1〜50年です。
